func BenchmarkPoseidon2Width8(b *testing.B) {
	h := NewPermutation(8, 6, 17)

	var tmp [8]fr.Element
	for i := range tmp {
		tmp[i].MustSetRandom()
	}
	b.ResetTimer()
	for range b.N {
		h.Permutation(tmp[:])
	}
}

